function agentCloud(seed,count=180,radius=64){return Array.from({length:count},(_,i)=>{const angle=i*2.39996+seed,r=Math.sqrt((i+.5)/count)*radius,w=1+.1*Math.sin(angle*3+seed),x=Math.cos(angle)*r*w,y=Math.sin(angle)*r*(.88+.08*Math.cos(angle*2));return `<circle cx="${x.toFixed(2)}" cy="${y.toFixed(2)}" r="${(i%7===0?2.15:1+(i%3)*.23).toFixed(2)}" opacity="${(.3+(i%7)/10).toFixed(2)}"/>`;}).join('');}
function swarmOrb(id,x,y,label,subtitle,seed,large=false){return `<g class="br-swarm-node" data-swarm-node="${id}" transform="translate(${x} ${y})"><circle class="br-orb-halo" r="${large?114:100}" fill="url(#br-orb-glow)"/><circle class="br-orb-boundary" r="${large?77:70}"/><circle class="br-orb-orbit" r="${large?86:79}"/><g class="br-agent-cloud" style="--br-orbit:${12+seed*2}s">${agentCloud(seed,large?260:190,large?71:63)}</g><circle class="br-orb-center" r="${large?10:8}"/><text class="br-swarm-node-title" text-anchor="middle" y="96">${label}</text><text class="br-swarm-node-sub" text-anchor="middle" y="118">${subtitle}</text><text class="br-node-owner" text-anchor="middle" y="-94">ATIENDE ESTE CASO</text></g>`;}
